  // Автоматическая генерация конфигурации для новых мобов
  "autoGenerate": true,

  // Спавн мобов с естественным зарядом (например, заряженные криперы)
  "NaturallyCharged": true,

  // Необходимость дождя для естественного заряда (только при NaturallyCharged=true)
  "NaturallyChargedNeedRain": true,

  // Вероятность получения заряда при попадании молнии (0,0–1,0)
